const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const windhoek = ee.Geometry.Point(17.083333, -22.566667); // Windhoek, Namibia
  const analysisArea = windhoek.buffer(5000); // 5 km buffer around Windhoek

  // Date ranges for comparison (approx. +/- 7 days around the specified date)
  const date2021_start = '2021-02-01';
  const date2021_end = '2021-02-14'; // Includes Feb 7, 2021

  const date2020_start = '2020-01-22';
  const date2020_end = '2020-02-05'; // Includes Jan 29, 2020

  const scale = 1000; // Resolution for analysis, 1km to avoid memory issues and get regional avg

  // Function to mask clouds in Sentinel-2 SR data
  function maskS2clouds(image) {
    const s2CloudMask = image.select('SCL');
    // Clouds, cloud shadows, cirrus, snow/ice
    const cloudClasses = ee.List([3, 8, 9, 10, 11]);
    const cloudMask = s2CloudMask.eq(cloudClasses.get(0))
      .or(s2CloudMask.eq(cloudClasses.get(1)))
      .or(s2CloudMask.eq(cloudClasses.get(2)))
      .or(s2CloudMask.eq(cloudClasses.get(3)))
      .or(s2CloudMask.eq(cloudClasses.get(4)))
      .focal_min(3); // Apply a focal min to dilate the mask slightly

    return image.updateMask(cloudMask.not()).copyProperties(image, ['system:time_start']);
  }

  // Function to calculate NDVI
  function addNDVI(image) {
    return image.addBands(image.normalizedDifference(['B8', 'B4']).rename('NDVI'));
  }

  // 2. Data Acquisition & Check
  const collection2021 = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(analysisArea)
    .filterDate(date2021_start, date2021_end)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 70)) // Initial cloud filter
    .map(maskS2clouds)
    .map(addNDVI);

  const collection2020 = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(analysisArea)
    .filterDate(date2020_start, date2020_end)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 70)) // Initial cloud filter
    .map(maskS2clouds)
    .map(addNDVI);

  const size2021 = await collection2021.size().getInfo();
  const size2020 = await collection2020.size().getInfo();

  if (size2021 === 0 || size2020 === 0) {
    console.log(`2021 Images: ${size2021}`);
    console.log(`2020 Images: ${size2020}`);
    console.log("C1");
    return;
  }

  // Take the median image for each period to represent the greenness
  const medianNDVI2021 = collection2021.select('NDVI').median().clip(analysisArea);
  const medianNDVI2020 = collection2020.select('NDVI').median().clip(analysisArea);

  // 3. Processing & Calculation
  // Calculate valid pixel count for 2021
  const count2021 = await medianNDVI2021.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: analysisArea,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  // Calculate valid pixel count for 2020
  const count2020 = await medianNDVI2020.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: analysisArea,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (count2021 === 0 || count2020 === 0) {
    console.log(`2021 Images: ${size2021}, Valid Pixels: ${count2021}`);
    console.log(`2020 Images: ${size2020}, Valid Pixels: ${count2020}`);
    console.log("C2");
    return;
  }

  const meanNDVI2021 = await medianNDVI2021.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: analysisArea,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const meanNDVI2020 = await medianNDVI2020.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: analysisArea,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  // 4. Validation & Final Answer
  if (meanNDVI2021 === null || isNaN(meanNDVI2021) ||
    meanNDVI2020 === null || isNaN(meanNDVI2020)) {
    console.log("C3");
    return;
  }

  console.log(`2021 Images: ${size2021} (Valid Pixels: ${count2021})`);
  console.log(`2020 Images: ${size2020} (Valid Pixels: ${count2020})`);
  console.log(`Mean NDVI 2021 (Feb 1-14): ${meanNDVI2021.toFixed(3)}`);
  console.log(`Mean NDVI 2020 (Jan 22-Feb 5): ${meanNDVI2020.toFixed(3)}`);

  if (meanNDVI2021 > meanNDVI2020) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
